@functools.lru_cache(maxsize=None)
def piece_image(symbol: str):
    """RGBA array for one piece symbol ('P'…'k'; uppercase = white)."""
    name = ("w" if symbol.isupper() else "b") + symbol.lower()
    png = base64.b64decode("".join(_ART[name].split()))
    return plt.imread(io.BytesIO(png), format="png")


def draw_piece(ax, symbol: str, x: float, y: float, *, size: float = .88,
               zorder: int = 4, alpha: float = 1.0):
    """Draw one cburnett piece centred on (x, y) in data coordinates, occupying
    `size` of a one-unit square — matching the app's miniboards, whose
    `.miniboard img.pc` is 88% (the main board's `.sq img.pc` is 87%).

    `zorder` and `alpha` pass through to the imshow, so a caller can stack a
    piece over a heat square or dim one that's out of attribution."""
    half = size / 2
    im = ax.imshow(piece_image(symbol), zorder=zorder, alpha=alpha,
                   extent=(x - half, x + half, y - half, y + half),
                   interpolation="antialiased")
    im.set_clip_on(False)
    return im


def _regenerate():
    """Rasterise `pieces.py`'s SVGs and rewrite this file's `_ART` block in place.

    Run only if the piece set changes. Kept here rather than in a sibling script so
    the artwork and the code that rebuilds it cannot drift apart."""
    import re
    from pathlib import Path

    import cairosvg

    from .pieces import PIECE_URI

    entries = []
    for sym, uri in sorted(PIECE_URI.items()):
        svg = base64.b64decode(uri.split(",", 1)[1])
        png = cairosvg.svg2png(bytestring=svg, output_width=PX, output_height=PX)
        name = ("w" if sym.isupper() else "b") + sym.lower()
        entries.append(_render_entry(name, base64.b64encode(png).decode("ascii")))
        print(name)

    src = Path(__file__).resolve()
    text = src.read_text()
    block = "_ART = {\n" + "".join(entries) + "}\n"
    text = re.sub(r"_ART = \{.*?\n\}\n", block, text, count=1, flags=re.S)
    src.write_text(text)


def _render_entry(name: str, b64: str) -> str:
    body = "\n".join("        " + b64[i:i + 88] for i in range(0, len(b64), 88))
    return f'    "{name}": """\n{body}\n""",\n'


if __name__ == "__main__":
    _regenerate()
